// Khi đã đặt khối trước cảm biến:
read_color(); // Tự đọc nhiều mẫu, báo Serial/LED
if (is_color(BLUE)) {
  Serial.println("Blue block"); // Không cần khai báo biến
}
// Hiệu chuẩn: đặt khối đỏ rồi gọi calibrate_color(RED).
